// Extract post data from Airtable record
const item = $input.first();
const fields = item.json.fields || item.json;

// Parse content brief to extract slot if embedded
const brief = fields['Content Brief'] || '';
const slotMatch = brief.match(/Slot: (morning|evening)/i);
const slot = slotMatch ? slotMatch[1] : 'morning';
const cleanBrief = brief.replace(/ \| Slot: (morning|evening)/i, '').trim();

return [{
  json: {
    recordId: item.json.id || '',
    title: fields.Title || 'Mankind AI Post',
    pillar: fields.Pillar || '',
    hookNumber: fields['Hook #'] || '',
    contentBrief: cleanBrief,
    videoFormat: fields['Video Format'] || '60-90s Research/Demo',
    date: fields.Date || '',
    slot
  }
}];

values.content:
=Generate 2 social media captions for a Mankind AI post.

Post Details:
- Title: {{ $json.title }}
- Content Pillar: {{ $json.pillar }}
- Hook: {{ $json.hookNumber }}
- Content Brief: {{ $json.contentBrief }}
- Video Format: {{ $json.videoFormat }}
- Posting Slot: {{ $json.slot }} ({{ $json.slot === 'morning' ? 'educational/informational tone' : 'results-focused/demo tone' }})

Return ONLY valid JSON with these exact keys (no markdown, no code blocks):
{
  "tiktok": "Hook-first caption. Max 150 chars. Punchy and direct. End with 1-2 hashtags: #MankindAI and one trending tag like #AITools or #Automation",
  "linkedin": "Professional 2-4 sentence caption for business owners and decision-makers. Start with a bold statement or question. Include the insight or result. End with a question or CTA. No hashtags. Mention mankindaitech.com naturally."
}

parameters.jsCode:
const geminiOutput = $input.first().json;
const postData = $('Extract Post Data').first().json;

let responseText = '';
if (typeof geminiOutput === 'string') responseText = geminiOutput;
else if (geminiOutput.response) responseText = String(geminiOutput.response);
else if (geminiOutput.text) responseText = String(geminiOutput.text);
else if (geminiOutput.content) responseText = String(geminiOutput.content);
else if (geminiOutput.output) responseText = String(geminiOutput.output);
else responseText = JSON.stringify(geminiOutput);

let captionsData;
try {
  let jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/```\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/(\{[\s\S]*\})/);
  const jsonString = jsonMatch ? jsonMatch[1].trim() : responseText.trim();
  captionsData = JSON.parse(jsonString);
} catch (e) {
  captionsData = {
    tiktok: `${postData.title} — AI that works for your business. #MankindAI #AITools`,
    linkedin: `At Mankind AI, we help business owners implement AI that saves time and drives real results. ${postData.contentBrief} Ready to see what AI can do for your business? Visit mankindaitech.com`
  };
}

return [{
  json: {
    recordId: postData.recordId,
    tiktokCaption: captionsData.tiktok || '',
    linkedinCaption: captionsData.linkedin || ''
  }
}];
